import path from 'node:path';

const quote = JSON.stringify;
export const generatedHeader = '// Generated by BitaKit. Do not edit.';
/** Single-quoted module specifiers, matching the style of hand-written imports. */
export const specifier = (value) =>
  `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

/**
 * The imports and type entries of one generated file. The client configuration and the server
 * file each have their own emitter, so a file's names (`entryN`, `moduleN`, `fileN`,
 * `normalizeN`) and their order depend only on what that file imports. `typedKind` decides which
 * integration kinds' type maps this file augments (the server file leaves client and both kinds
 * to the client file, which is in the same program).
 */
export function createEmitter(output, relativeTo, { typedKind = () => true } = {}) {
  const imports = [];
  let serial = 0;
  /** The next free number for a name in this file. */
  const next = () => serial++;
  const importFile = (file, namespace = false) => {
    const name = `${namespace ? 'module' : 'entry'}${next()}`;
    let relative = path
      .relative(output, file)
      .replaceAll(path.sep, '/')
      .replace(/\.tsx?$/, '');
    if (!relative.startsWith('.')) relative = `./${relative}`;
    imports.push(
      namespace
        ? `import * as ${name} from ${specifier(relative)};`
        : `import ${name} from ${specifier(relative)};`,
    );
    return name;
  };
  const types = {
    services: [],
    actions: [],
    events: [],
    cancelable: [],
    settings: [],
    slots: [],
    configs: [],
    permissions: [],
    roles: [],
  };
  /** One `fileN = discoveredFile(entryN, path, source)` per entry; returns the `fileN` names. */
  const fileEntries = (entries) =>
    entries.map((entry) => {
      const imported = importFile(entry.file);
      const name = `file${next()}`;
      imports.push(
        `const ${name} = discoveredFile(${imported}, ${quote(entry.path.join('.'))}, ${quote(relativeTo(entry.file))});`,
      );
      return name;
    });
  /** The `discover*` call of a built-in kind; records the file's type entries. */
  const emit = (kind, entries, moduleId) => {
    const names = fileEntries(entries);
    if (kind === 'actions')
      for (const name of names)
        types.actions.push(`DiscoveredActionEntry<typeof ${name}, ${quote(moduleId)}>`);
    if (kind === 'services')
      for (const name of names)
        types.services.push(`DiscoveredServiceEntry<typeof ${name}, ${quote(moduleId)}>`);
    if (kind === 'events')
      for (const name of names) {
        types.events.push(`DiscoveredEventsEntry<typeof ${name}, ${quote(moduleId)}>`);
        types.cancelable.push(`DiscoveredCancelableEntry<typeof ${name}, ${quote(moduleId)}>`);
      }
    if (kind === 'settings')
      for (const name of names)
        types.settings.push(`DiscoveredSettingsEntry<typeof ${name}, ${quote(moduleId)}>`);
    if (kind === 'slotDefinitions')
      for (const name of names)
        types.slots.push(`DiscoveredSlotEntry<typeof ${name}, ${quote(moduleId)}>`);
    if (kind === 'configs')
      types.configs.push(
        `${quote(moduleId)}: ${names.map((name) => `DiscoveredConfigEntry<typeof ${name}>`).join(' & ') || '{}'};`,
      );
    const fn = {
      actions: 'discoverActions',
      services: 'discoverServices',
      slotDefinitions: 'discoverSlots',
      interceptors: 'discoverInterceptors',
      installers: 'discoverInstallers',
      configs: 'discoverConfig',
      events: 'discoverEvents',
      settings: 'discoverSettings',
    }[kind];
    const extra =
      kind === 'actions' || kind === 'services' || kind === 'slotDefinitions'
        ? `, ${quote(moduleId)}`
        : '';
    return `${fn}([${names.join(', ')}]${extra})`;
  };
  const normalizers = new Map();
  /** Integration kinds with a type map, by name: `{ kind, index, entries }`. */
  const kindTypes = new Map();
  /**
   * A module's `contributions` object: `entriesByKind[index]` holds the files of `kinds[index]`.
   * Names use the kind's index, so they stay stable while other kinds come and go.
   */
  const contributions = (kinds, entriesByKind, moduleId) => {
    const parts = [];
    kinds.forEach((kind, index) => {
      const entries = entriesByKind[index];
      if (!entries.length) return;
      if (!normalizers.has(kind.name)) {
        const alias = `normalize${index}`;
        imports.push(`import { ${kind.normalize} as ${alias} } from ${specifier(kind.from)};`);
        normalizers.set(kind.name, alias);
      }
      const names = fileEntries(entries);
      if (kind.types && typedKind(kind)) {
        if (!kindTypes.has(kind.name)) {
          imports.push(
            `import type { ${kind.types.entry} as KindEntry${index} } from ${specifier(kind.from)};`,
          );
          kindTypes.set(kind.name, { kind, index, entries: [] });
        }
        kindTypes
          .get(kind.name)
          .entries.push(
            ...names.map((name) => `KindEntry${index}<typeof ${name}, ${quote(moduleId)}>`),
          );
      }
      parts.push(
        `${quote(kind.name)}: ${normalizers.get(kind.name)}([${names.join(', ')}], ${quote(moduleId)})`,
      );
    });
    return `{ ${parts.join(', ')} }`;
  };
  /** `declare module '<from>'` augmentations of the integration kinds' type maps. */
  const kindDeclarations = () =>
    [...kindTypes.values()]
      .map(
        ({ kind, index, entries }) =>
          `type KindMap${index} = ${entries.join(' & ')};\ndeclare module ${specifier(kind.from)} { interface ${kind.types.map} extends KindMap${index} {} }`,
      )
      .join('\n');
  return {
    imports,
    types,
    next,
    importFile,
    fileEntries,
    emit,
    contributions,
    kindDeclarations,
  };
}
